entrada= input('Você quer "entrar" ou "sair"? ')
if entrada == "entrar":
    print("Você entrou no sistema.")
elif entrada == "sair":
    print("Você saiu do sistema.")
else:
    print("Opção inválida.")
# O código acima é um exemplo de estrutura condicional em Python.
# Ele verifica a entrada do usuário e executa diferentes ações com base na opção escolhida.